SELECT
,
p.place_name AS placeName,

FROM att_qrcode q
LEFT JOIN biz_place p ON p.id = q.place_id

    AND q.place_id = #{placeId}
    AND q.status = #{status}
    AND q.qr_type = #{qrType}

ORDER BY q.id DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM att_qrcode q

    AND q.place_id = #{placeId}
    AND q.status = #{status}
    AND q.qr_type = #{qrType}

